import {makePlayer,rollChoices,ENEMIES,MAX_ENEMIES,MAX_PARTICLES,BOSS_TIME,WORLD_SIZE,RARITIES} from './data.js';
import {seeded,createWorld,moveEntity,distance,SpatialHash,clamp} from './world.js';
import {ENEMY_STATES,updateEnemyAI} from './ai.js';
import {findNewSynergies,getSynergyModifiers} from './synergies.js';
import {applyEncounter,createEncounters,encounterMarkers} from './encounters.js';
/** Pure simulation. No DOM/browser dependency; renderer and UI subscribe through events. */
export class Game{
 constructor({seed=Date.now()>>>0,onEvent=()=>{}}={}){this.onEvent=onEvent;this.reset(seed);this.state='menu'}
 reset(seed=Date.now()>>>0){this.seed=seed;this.rng=seeded(seed^0xBADCAFE);this.world=createWorld(seed);this.player=makePlayer();this.enemies=[];this.shots=[];this.hostile=[];this.encounters=createEncounters(seed,this.world);this.gems=encounterMarkers(this.encounters);this.particles=[];this.texts=[];this.zones=[];this.owned={};this.activeSynergyIds=new Set();this.time=0;this.kills=0;this.spawnClock=0;this.fireClock=0;this.orbitClock=0;this.bossSpawned=false;this.boss=null;this.shake=0;this.flash=0;this.nextId=1;this.state='playing';this.grid=new SpatialHash(100);this.choices=[];this.onEvent('reset')}
 emit(type,data){this.onEvent(type,data)}
 pause(){if(this.state==='playing'){this.state='paused';this.emit('pause')}else if(this.state==='paused'){this.state='playing';this.emit('resume')}}
 dash(){const p=this.player;if(this.state!=='playing'||p.dashCooldown>0)return false;p.dashCooldown=3;p.dashTime=.18;p.invincible=.35;this.burst(p.x,p.y,'#d9dfb4',16);this.emit('sound','dash');return true}
 spawn(type,x,y){const stats=ENEMIES[type],scale=type==='boss'?1:1+this.time/240;const e={...stats,maxHp:stats.hp*scale,hp:stats.hp*scale,type,x,y,id:this.nextId++,slow:0,hit:0,cooldown:.4+this.rng()*.6,attack:0,aim:0,phase:0,state:ENEMY_STATES.SPAWN,stateTime:0,blockedTime:0,sidestep:1};moveEntity(e,0,0,this.world);this.enemies.push(e);return e}
 spawnWave(){if(this.enemies.length>=MAX_ENEMIES)return;const p=this.player,n=Math.min(4,1+Math.floor(this.time/55));for(let i=0;i<n&&this.enemies.length<MAX_ENEMIES;i++){const a=this.rng()*Math.PI*2,r=490+this.rng()*190,x=clamp(p.x+Math.cos(a)*r,65,WORLD_SIZE-65),y=clamp(p.y+Math.sin(a)*r,65,WORLD_SIZE-65),roll=this.rng();let type='crawler';if(this.time>22&&roll<.27)type='runner';if(this.time>48&&roll>.77)type='shaman';if(this.time>90&&roll>.90)type='brute';this.spawn(type,x,y)}}
 summonBoss(){this.bossSpawned=true;const p=this.player,a=this.rng()*6.28;this.boss=this.spawn('boss',clamp(p.x+Math.cos(a)*440,90,WORLD_SIZE-90),clamp(p.y+Math.sin(a)*440,90,WORLD_SIZE-90));this.emit('boss');this.emit('sound','boss');this.shake=7}
 burst(x,y,color,count=8){for(let i=0;i<count&&this.particles.length<MAX_PARTICLES;i++){const a=this.rng()*6.28,s=25+this.rng()*110;this.particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.25+this.rng()*.35,max:.6,color,r:1+this.rng()*3})}}
 hitEnemy(e,damage){if(e.hp<=0)return;e.hp-=damage;e.hit=.12;this.burst(e.x,e.y,e.type==='boss'?'#f8b768':'#c9d5a0',4);if(this.texts.length<70)this.texts.push({x:e.x,y:e.y-20,text:Math.round(damage),life:.65,color:'#f7d5a0'});this.emit('sound','hit');if(e.hp<=0){this.kills++;this.burst(e.x,e.y,'#ddba73',12);if(this.gems.length<250)this.gems.push({x:e.x,y:e.y,value:e.xp,r:5});else{const g=this.gems.reduce((a,b)=>distance(a,e)<distance(b,e)?a:b);g.value+=e.xp}if(e.type==='boss'){this.state='won';this.shake=12;this.emit('sound','win');this.emit('end',true)}else if(this.rng()<.025)this.gems.push({x:e.x+8,y:e.y,value:0,heal:12,r:6})}}
 hurt(amount){const p=this.player;if(p.invincible>0||this.state!=='playing')return;p.hp=Math.max(0,p.hp-Math.max(1,amount-p.armor));p.invincible=.7;this.shake=7;this.flash=.2;this.burst(p.x,p.y,'#eb8f77',13);this.emit('sound','hurt');if(p.hp<=0){this.state='dead';this.emit('sound','die');this.emit('end',false)}}
 checkLevel(){const p=this.player;if(p.xp<p.nextXp||this.state!=='playing')return;p.xp-=p.nextXp;p.level++;p.nextXp=Math.round(p.nextXp*1.18+4);p.hp=Math.min(p.maxHp,p.hp+10);this.choices=rollChoices(this.rng,this.owned);if(!this.choices.length){p.hp=p.maxHp;return}this.state='levelup';this.emit('sound','level');this.emit('levelup',this.choices)}
 choose(index){if(this.state!=='levelup'||!this.choices[index])return false;const {skill,rarity}=this.choices[index];skill.apply(this.player,RARITIES[rarity].mult);this.owned[skill.id]={skill,rarity,count:(this.owned[skill.id]?.count||0)+1};const awakened=findNewSynergies(this.owned,this.activeSynergyIds);for(const synergy of awakened){this.activeSynergyIds.add(synergy.id);this.emit('synergy',synergy)}this.choices=[];this.state='playing';this.emit('upgrade');this.checkLevel();return true}
 shoot(){const p=this.player;let target=null,best=560;for(const e of this.enemies){const d=distance(e,p);if(e.hp>0&&d<best){target=e;best=d}}if(!target)return false;const a=Math.atan2(target.y-p.y,target.x-p.x),n=p.projectiles;for(let i=0;i<n;i++){const angle=a+(i-(n-1)/2)*.16;if(this.shots.length<180)this.shots.push({x:p.x,y:p.y-7,vx:Math.cos(angle)*380,vy:Math.sin(angle)*380,life:1.75,r:6,damage:p.damage,pierce:p.pierce,hit:new Set()})}p.cast=.15;this.emit('sound','cast');return true}
 fireHostile(e,a,n=1,speed=140){for(let i=0;i<n&&this.hostile.length<220;i++){const angle=a+(i-(n-1)/2)*.20;this.hostile.push({x:e.x,y:e.y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,life:5,r:e.type==='boss'?8:6,damage:e.damage})}}
 step(dt,input={x:0,y:0}){
 if(this.state!=='playing')return;dt=Math.min(.05,Math.max(0,dt));this.time+=dt;const p=this.player;
 p.invincible=Math.max(0,p.invincible-dt);p.dashCooldown=Math.max(0,p.dashCooldown-dt);p.dashTime=Math.max(0,p.dashTime-dt);p.cast=Math.max(0,p.cast-dt);p.hp=Math.min(p.maxHp,p.hp+p.regen*dt);this.shake=Math.max(0,this.shake-dt*25);this.flash=Math.max(0,this.flash-dt);
 if(Math.hypot(input.x,input.y)>.05){const len=Math.max(1,Math.hypot(input.x,input.y));p.dirX=input.x/len;p.dirY=input.y/len;p.walk+=dt*12}const dx=p.dashTime>0?p.dirX:input.x,dy=p.dashTime>0?p.dirY:input.y,vel=p.speed*(p.dashTime>0?3.7:1);moveEntity(p,dx*vel*dt,dy*vel*dt,this.world);if(p.dashTime>0)this.burst(p.x,p.y,'#cad9ba',2);
 this.spawnClock-=dt;if(this.spawnClock<=0){this.spawnWave();this.spawnClock=Math.max(.45,1.5-this.time/200)}
 if(this.time>=BOSS_TIME&&!this.bossSpawned)this.summonBoss();
 this.fireClock-=dt;if(this.fireClock<=0&&this.shoot())this.fireClock=1/p.attackRate;
 this.grid.clear();for(const e of this.enemies)if(e.hp>0)this.grid.add(e);
 for(const e of this.enemies){if(e.hp>0)updateEnemyAI(this,e,dt)}
 // Rebuild after movement so projectile queries use current positions.
 this.grid.clear();for(const e of this.enemies)if(e.hp>0)this.grid.add(e);
 const synergy=getSynergyModifiers(this.owned);
 for(const s of this.shots){s.life-=dt;s.x+=s.vx*dt;s.y+=s.vy*dt;if(this.world.hash.query(s.x,s.y,50).some(o=>distance(s,o)<o.r+s.r)){s.life=0;this.burst(s.x,s.y,'#e8b474',3);continue}for(const e of this.grid.query(s.x,s.y,65)){if(e.hp<=0||s.hit.has(e.id)||distance(s,e)>s.r+e.r)continue;s.hit.add(e.id);const direct=s.damage*(e.slow>0?synergy.slowedDirect:1);this.hitEnemy(e,direct);if(p.slow)e.slow=2;for(const other of this.grid.query(e.x,e.y,p.blast+50)){if(other!==e&&other.hp>0&&distance(e,other)<p.blast+other.r)this.hitEnemy(other,s.damage*.45*synergy.splashDamage)}this.burst(s.x,s.y,'#ffaf57',7);if(s.pierce--<=0){s.life=0;break}}}
 for(const s of this.hostile){s.life-=dt;s.x+=s.vx*dt;s.y+=s.vy*dt;if(distance(s,p)<p.r+s.r){this.hurt(s.damage);s.life=0}if(this.world.hash.query(s.x,s.y,50).some(o=>distance(s,o)<s.r+o.r))s.life=0}
 for(const z of this.zones){z.timer-=dt;if(z.timer<=0){z.life-=dt;z.active=true;if(distance(z,p)<z.r+p.r)this.hurt(z.damage)}}this.zones=this.zones.filter(z=>z.life>0);
 this.orbitClock-=dt;if(p.orbits&&this.orbitClock<=0){this.orbitClock=.25;for(let i=0;i<p.orbits;i++){const a=this.time*2.6+i*6.28/p.orbits,o={x:p.x+Math.cos(a)*66,y:p.y+Math.sin(a)*66};for(const e of this.grid.query(o.x,o.y,65))if(distance(e,o)<e.r+14)this.hitEnemy(e,p.damage*.55*synergy.orbitDamage)}}
 for(const g of this.gems){const d=distance(g,p);if(!g.encounterId&&d<p.magnet){const a=Math.atan2(p.y-g.y,p.x-g.x),v=Math.min(d,Math.max(160,450-d)*dt);g.x+=Math.cos(a)*v;g.y+=Math.sin(a)*v}if(distance(g,p)<p.r+(g.encounterId?15:10)){if(g.encounterId){const encounter=this.encounters.find(e=>e.id===g.encounterId);applyEncounter(this,encounter)}else if(g.heal)p.hp=Math.min(p.maxHp,p.hp+g.heal);else p.xp+=g.value;g.dead=true;this.emit('sound','pickup')}}
 this.gems=this.gems.filter(g=>!g.dead);this.enemies=this.enemies.filter(e=>e.hp>0);this.shots=this.shots.filter(s=>s.life>0);this.hostile=this.hostile.filter(s=>s.life>0);
 for(const q of this.particles){q.life-=dt;q.x+=q.vx*dt;q.y+=q.vy*dt;q.vx*=.95;q.vy*=.95}this.particles=this.particles.filter(q=>q.life>0);for(const t of this.texts){t.y-=dt*28;t.life-=dt}this.texts=this.texts.filter(t=>t.life>0);this.checkLevel();
 }
}
